query AdsHeartbeatSep13EveningOrderCounts {
  shop { id name ianaTimezone }
  allNew: ordersCount(query:"created_at:>='2026-09-13T14:55:52Z' created_at:<'2026-09-13T19:01:29Z'",limit:null) { count precision }
  webNonTest: ordersCount(query:"created_at:>='2026-09-13T14:55:52Z' created_at:<'2026-09-13T19:01:29Z' source_name:web test:false",limit:null) { count precision }
  paidWebNonTest: ordersCount(query:"created_at:>='2026-09-13T14:55:52Z' created_at:<'2026-09-13T19:01:29Z' source_name:web test:false financial_status:paid",limit:null) { count precision }
}
